#!/bin/sh
# Route the board with vcad (~30 min), check it in KiCad, render it. Run build.sh first.
set -e
cd "$(dirname "$0")"
VCAD=${VCAD:-vcad}
KICAD_CLI=${KICAD_CLI:-/Applications/KiCad/KiCad.app/Contents/MacOS/kicad-cli}
export VCAD_KICAD_FOOTPRINTS="$(cd ../../brand && pwd):$(pwd)${VCAD_KICAD_FOOTPRINTS:+:$VCAD_KICAD_FOOTPRINTS}"
# RENDER_ONLY=1 skips routing and DRC and just re-renders the board on disk.
if [ "${RENDER_ONLY:-0}" != 1 ]; then
# The 48 V path (VIN, VBUS_SW, VBUS, BRK_R) has its own pour regions on F.Cu
# (EcadPourRect, generated by place.py): routed as traces, reinforced by the pour.
# 12 V and 5 V are traced at their class width; declaring their currents keeps
# them traces rather than pours.
$VCAD route arm_controller.loon arm_controller.kicad_pcb --current +12V=1 --current +5V=1.5 --effort 3 --priority ETH_TXP --priority ETH_TXN --priority ETH_RXP --priority ETH_RXN --priority HS_SENSE --priority HS_EN --priority AUX_IO --priority ETH_REFCLK --priority ETH_TXD1 --priority SPI_MOSI --priority CANX_H --priority ETH_REFCLK --priority CANX_INT --priority BK2_FB
# kicad-cli 9 DRC does not refill zones: fill them with KiCad's own filler first
KICAD_PY=${KICAD_PY:-$(ls /Applications/KiCad/KiCad.app/Contents/Frameworks/Python.framework/Versions/*/bin/python3 | head -1)}
python3 set_finish.py arm_controller.kicad_pcb                       # black mask, muni orange silk, ENIG
"$KICAD_PY" make_models.py arm_controller.kicad_pcb 2>/dev/null | grep -v swig || true   # boxes for missing 3D models
rm -f added.txt
echo "premium: $("$KICAD_PY" premium.py arm_controller.kicad_pcb 2>/dev/null | grep -E '^[0-9]+ [0-9]+$' | tail -1) (front designators to fab, teardrops)"
"$KICAD_PY" fill_zones.py arm_controller.kicad_pcb
# ground stitching: via fence round the edge and a grid in open ground, then refill
echo "stitching vias: $("$KICAD_PY" stitch.py arm_controller.kicad_pcb 2>/dev/null | grep -E '^[0-9]+$' | tail -1)"
"$KICAD_PY" fill_zones.py arm_controller.kicad_pcb >/dev/null 2>&1
# router leftovers KiCad calls dangling: drop them and refill until none remain
for _ in 1 2 3 4 5; do
  $KICAD_CLI pcb drc --format json -o drc.json arm_controller.kicad_pcb >/dev/null 2>&1
  n=$("$KICAD_PY" drop_dangling.py arm_controller.kicad_pcb drc.json 2>/dev/null | grep -E '^[0-9]+$' | tail -1)
  [ "${n:-0}" = 0 ] && break
  echo "dropped $n dangling items"
  "$KICAD_PY" fill_zones.py arm_controller.kicad_pcb >/dev/null 2>&1
done
# close what is still open, by KiCad's own judgement: plane vias for stranded
# GND/+3V3 pads, short traces for the rest; then drop any addition DRC flags
# (teardrops from premium.py are in added.txt too: a wedge DRC dislikes goes)
for _ in 1 2 3; do
  $KICAD_CLI pcb drc --format json -o drc.json arm_controller.kicad_pcb >/dev/null 2>&1
  n=$("$KICAD_PY" close_unconnected.py arm_controller.kicad_pcb drc.json 2>/dev/null | grep -E '^[0-9]+$' | tail -1)
  [ "${n:-0}" = 0 ] && break
  "$KICAD_PY" fill_zones.py arm_controller.kicad_pcb >/dev/null 2>&1
  $KICAD_CLI pcb drc --format json -o drc.json arm_controller.kicad_pcb >/dev/null 2>&1
  bad=$("$KICAD_PY" drop_added.py arm_controller.kicad_pcb drc.json 2>/dev/null | grep -E '^[0-9]+$' | tail -1)
  echo "closed $n open connections (removed $bad that broke a rule)"
  "$KICAD_PY" fill_zones.py arm_controller.kicad_pcb >/dev/null 2>&1
done
rm -f drc.json added.txt
$KICAD_CLI pcb drc --format report -o drc.rpt arm_controller.kicad_pcb 2>/dev/null | grep -E "violations|unconnected" || true
fi

# renders: top, bottom, 3D (RENDER=0 skips; route_best.sh renders only the board it keeps)
if [ "${RENDER:-1}" != 0 ]; then
  mkdir -p render
  $KICAD_CLI pcb render --side top --width 2400 --height 800 --quality high -o render/board_top.png arm_controller.kicad_pcb >/dev/null 2>&1
  $KICAD_CLI pcb render --side bottom --width 2400 --height 800 --quality high -o render/board_bottom.png arm_controller.kicad_pcb >/dev/null 2>&1
  # the inner quotes keep kicad-cli from reading '-45,...' as a flag
  $KICAD_CLI pcb render --side top --rotate "'-45,0,25'" --perspective --zoom 1.6 --width 2400 --height 1400 --quality high -o render/board_3d.png arm_controller.kicad_pcb >/dev/null 2>&1
  for f in render/board_top.png render/board_bottom.png render/board_3d.png; do
    magick "$f" -trim +repage -bordercolor white -border 20 "$f"
  done
  echo "rendered render/board_{top,bottom,3d}.png"
fi
